begin;

delete from public.sections where page_id = (select id from public.pages where slug = '/local-seo-services');
insert into public.sections (page_id, key, type, tone, data, position) select id, 'hero', 'heroSplit', NULL, '{"eyebrow":"Local SEO Services","heading":"Get Found Where Your Customers Are Looking","body":"Local SEO is the work of appearing when somebody nearby searches for what you do. It runs across your Google Business Profile, your listings, your reviews and your service pages, and it is measured across your whole service area rather than as one number.","primaryCta":{"label":"View Local SEO Packages","href":"/monthly-seo-packages#local"},"showcase":[{"kind":"share","label":"A month of Citywide","title":"Where the Work Goes","unit":"tasks in a Citywide month, at the published maximums","series":[{"label":"Review replies","value":20},{"label":"Citations","value":15},{"label":"Profile posts","value":12},{"label":"Review requests","value":4}]},{"kind":"channels","label":"Three tiers","title":"Sized by Area","items":["Neighborhood","Citywide","Metro"]}]}'::jsonb, 0 from public.pages where slug = '/local-seo-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'audience-fit', 'cardGrid', 'surface', '{"variant":"cards","columns":4,"eyebrow":"Is This You","heading":"Who Local SEO Is For","body":"The first three sort by how customers reach you. The fourth is about scale, so a practice with four offices is both the third and the fourth.","cards":[{"title":"Storefront","icon":"storefront","body":"Customers come to you, and being findable on a map is most of the battle. Shops, showrooms, studios, gyms."},{"title":"Service Area","icon":"map-pin","body":"You travel to the customer, so you are ranked against an area rather than an address. Trades, contractors, mobile services."},{"title":"Appointment-Based","icon":"calendar","body":"Customers book time with you, and they compare two or three options before doing it. Practices, clinics, salons, consultants."},{"title":"Multi-Location","icon":"building","body":"Several locations competing across the same broad area. Each one needs its own profile, its own citations and its own tracking, or they compete with each other."}]}'::jsonb, 1 from public.pages where slug = '/local-seo-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'includes', 'cardGrid', 'white', '{"variant":"cards","columns":3,"eyebrow":"What You Get","heading":"What Local SEO Includes","body":"Every package includes all six. Tiers differ by volume, not by what is included.","cards":[{"title":"SEO Strategy & Roadmap","icon":"compass","body":"A plan for the next quarter rather than a list of tasks, with the reasoning behind the order it runs in."},{"title":"Content & On-Page Optimization","icon":"pencil","body":"Service pages, titles, descriptions and on-page structure written for how people in your area actually search."},{"title":"Technical Monitoring","icon":"gauge","body":"Crawling, indexing and site health watched month to month, so a problem is found before it costs you visibility."},{"title":"Detailed Monthly Reporting","icon":"bar-chart","body":"What was tracked, what moved and what did not, in language that does not need translating."},{"title":"Monthly Project Recap","icon":"message-square","body":"A person walking through the month rather than a file dropped into an inbox, with room to ask questions."},{"title":"Review Management","icon":"star","body":"Review requests sent to real customers and replies written to what comes back, positive and negative alike."}]}'::jsonb, 2 from public.pages where slug = '/local-seo-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'visibility-system', 'cardGrid', 'surface', '{"variant":"cards","columns":5,"eyebrow":"The System","heading":"The Local Visibility System","body":"Five parts, worked together. Any one of them on its own tends to stall.","cards":[{"title":"Google Business Profile","icon":"storefront","body":"Categories, services, information, photos and posts. For many local searches the profile is what is being ranked.","href":"/google-business-profile-optimization"},{"title":"Citations & NAP Consistency","icon":"shield-check","body":"One standard for your name, address and phone number, applied across the listings that currently disagree with each other."},{"title":"Reviews","icon":"star","body":"Requests to real customers and replies to what arrives. Nothing fabricated, nothing incentivised."},{"title":"Local Search Grid Tracking","icon":"map-pin","body":"Visibility measured across a grid of points in your service area rather than as one blended rank, so you can see where you are strong and where you are not."},{"title":"Strategic SEO Pages","icon":"file-text","body":"Pages built for the services and areas worth competing for, rather than one page trying to hold all of them."}]}'::jsonb, 3 from public.pages where slug = '/local-seo-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'monthly-recap', 'reportingBlock', 'white', '{"eyebrow":"Reporting","heading":"The Monthly Recap","body":"Four questions, every month, in the same order. It arrives as a short video or on a call, whichever suits you, with the written version alongside it.","did":"Every task completed, named individually rather than summarised: the pages written or rewritten, the listings corrected and where they were corrected, the posts published, the reviews replied to, and the technical fixes made.","why":"The reasoning behind the order the work ran in. Which problem was costing the most visibility, what it was expected to affect, and what was deliberately left for later.","changed":"Grid visibility across the service area compared with last month, point by point rather than as one blended rank, alongside profile actions and what arrived through the site. Including the months where little moved, and why.","next":"What is queued for the coming month and in what order, written down before it starts, so the next recap is measured against something you already agreed to.","cta":{"label":"See How JMC Reports SEO Progress","href":"/seo-reporting"}}'::jsonb, 4 from public.pages where slug = '/local-seo-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'packages', 'pricingCards', 'surface', '{"eyebrow":"Pricing","heading":"Local SEO Packages","body":"Three tiers, sized by how much ground you are competing for. Every tier includes all six of the deliverables above.","packageIds":["local-neighborhood","local-citywide","local-metro"]}'::jsonb, 5 from public.pages where slug = '/local-seo-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'custom-scope', 'fullWidthText', 'surface', '{"heading":"Working With Something Bigger?","body":"If the scope is bigger or more involved than what is here, JMC will look at it and put together a quote. However many locations are involved, a business competing in local results is still a Local engagement.","cta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 6 from public.pages where slug = '/local-seo-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'sprint-callout', 'calloutBanner', 'white', '{"heading":"Or Start With a Launch Sprint","body":"The Neighborhood Launch Sprint is $799, one-time, completed within 30 days. It builds the local foundation and finishes with a 30-day roadmap. Begin monthly service within 30 days of the sprint finishing and the onboarding fee on any Local package is waived, up to $649.","primaryCta":{"label":"View Launch Sprints","href":"/launch-sprints"},"secondaryCta":{"label":"View Local SEO Packages","href":"/monthly-seo-packages#local"}}'::jsonb, 7 from public.pages where slug = '/local-seo-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'faq', 'faq', 'surface', '{"eyebrow":"Questions","heading":"Local SEO Questions","items":[{"question":"How long before there are results?","answer":"Local tends to move faster than national search because the competing field is smaller, and profile or listing corrections can show within weeks. Ranking movement across a service area is a longer arc, usually a few months before the shape of it is clear. Nobody can honestly give you a date, and the recap tells you which stage the work is at each month."},{"question":"Is there a contract?","answer":"Yes. Twelve months, then month to month, with 30 days written notice to end it. The term exists because the work compounds and a three-month engagement cannot show what a twelve-month one can."},{"question":"What does the onboarding fee cover?","answer":"The audit, tracking setup, the foundational on-page work and the local visibility setup: profile, categories, services, citations and the grid baseline. It is the work that has to happen once before the monthly work means anything."},{"question":"How is this different from Traditional SEO?","answer":"Local SEO is for businesses competing for customers in a defined area, however many locations they run in it. Traditional SEO is for businesses competing across multiple markets, multiple service lines, or genuinely competitive search. It is a difference in reach, not in size."},{"question":"Do you guarantee rankings?","answer":"No, and anyone who does is guessing. What is guaranteed is the scope, the reporting, and knowing exactly what was done and why."},{"question":"What is local search grid tracking?","answer":"Instead of checking your rank from one point, it checks from a grid of points across your service area. That matters because local results change street by street: you can be first near your own address and invisible four miles away, and one blended number hides that completely."},{"question":"What if the business is not in Houston?","answer":"Local SEO is not limited to the Houston area. JMC is based in League City and most clients are nearby, but the work is the same for a business competing in a defined area anywhere."}],"cta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 8 from public.pages where slug = '/local-seo-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'final-cta', 'finalCta', NULL, '{"heading":"Not Sure a Package Fits?","body":"Start with a visibility review instead. Where you appear across your service area today, what is holding it back, and which of those gaps is worth closing first — before anything is bought.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 9 from public.pages where slug = '/local-seo-services';
